CREATE TABLE IF NOT EXISTS users ( id TEXT PRIMARY KEY, provider TEXT NOT NULL, provider_id TEXT NOT NULL, login TEXT NOT NULL, avatar_url TEXT, provider_created_utc TEXT, created_utc TEXT NOT NULL, is_banned INTEGER NOT NULL DEFAULT 0, ban_reason TEXT, is_trusted INTEGER NOT NULL DEFAULT 0, UNIQUE (provider, provider_id) );
CREATE TABLE IF NOT EXISTS sessions ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, created_utc TEXT NOT NULL, expires_utc TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS sessions_user ON sessions (user_id);
CREATE TABLE IF NOT EXISTS posts ( id TEXT PRIMARY KEY, author_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, game TEXT NOT NULL, category TEXT NOT NULL, tags TEXT NOT NULL, content TEXT NOT NULL, sections TEXT NOT NULL, content_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'visible', created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL, removed_utc TEXT, likes INTEGER NOT NULL DEFAULT 0, helpful_yes INTEGER NOT NULL DEFAULT 0, helpful_no INTEGER NOT NULL DEFAULT 0, helpful_score REAL NOT NULL DEFAULT 0, imports INTEGER NOT NULL DEFAULT 0 );
CREATE INDEX IF NOT EXISTS posts_list ON posts (status, created_utc);
CREATE INDEX IF NOT EXISTS posts_author ON posts (author_id);
CREATE VIRTUAL TABLE IF NOT EXISTS posts_fts USING fts5 (post_id UNINDEXED, title, description, tags, game, category, tokenize = 'unicode61 remove_diacritics 2');
CREATE TABLE IF NOT EXISTS images ( id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, post_id TEXT, kind TEXT NOT NULL, status TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, has_alpha INTEGER NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL, thumb_mime TEXT NOT NULL, thumb_bytes INTEGER NOT NULL, storage_key TEXT NOT NULL, thumb_key TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, created_utc TEXT NOT NULL, deleted_utc TEXT );
CREATE INDEX IF NOT EXISTS images_post ON images (post_id);
CREATE INDEX IF NOT EXISTS images_owner ON images (owner_id);
CREATE TABLE IF NOT EXISTS upload_slots ( user_id TEXT NOT NULL, day TEXT NOT NULL, slot INTEGER NOT NULL, state TEXT NOT NULL, image_id TEXT, reserved_utc TEXT NOT NULL, PRIMARY KEY (user_id, day, slot) );
CREATE TABLE IF NOT EXISTS likes (user_id TEXT NOT NULL, post_id TEXT NOT NULL, created_utc TEXT NOT NULL, PRIMARY KEY (user_id, post_id));
CREATE TABLE IF NOT EXISTS bookmarks (user_id TEXT NOT NULL, post_id TEXT NOT NULL, created_utc TEXT NOT NULL, PRIMARY KEY (user_id, post_id));
CREATE TABLE IF NOT EXISTS helpful (user_id TEXT NOT NULL, post_id TEXT NOT NULL, helpful INTEGER NOT NULL, PRIMARY KEY (user_id, post_id));
CREATE TABLE IF NOT EXISTS imports (user_id TEXT NOT NULL, post_id TEXT NOT NULL, created_utc TEXT NOT NULL, PRIMARY KEY (user_id, post_id));
CREATE TABLE IF NOT EXISTS reports ( id TEXT PRIMARY KEY, post_id TEXT NOT NULL, reporter_id TEXT NOT NULL, reason TEXT NOT NULL, details TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_utc TEXT NOT NULL, UNIQUE (post_id, reporter_id) );
CREATE TABLE IF NOT EXISTS activity (user_id TEXT NOT NULL, kind TEXT NOT NULL, created_utc TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS activity_user ON activity (user_id, kind, created_utc);
CREATE TABLE IF NOT EXISTS mod_log (id TEXT PRIMARY KEY, admin_id TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, note TEXT, created_utc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media_blobs ( key TEXT PRIMARY KEY, content_type TEXT NOT NULL, data BLOB NOT NULL, bytes INTEGER NOT NULL, created_utc TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS evidence (key TEXT PRIMARY KEY, tweak TEXT NOT NULL, kind TEXT NOT NULL, game TEXT, cpu TEXT NOT NULL, gpu TEXT NOT NULL, ram_gb INTEGER NOT NULL, os_build INTEGER NOT NULL, app TEXT NOT NULL, metrics TEXT NOT NULL, day TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS evidence_tweak ON evidence (tweak);
CREATE TABLE IF NOT EXISTS evidence_quota (user_id TEXT NOT NULL, day TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (user_id, day));
